NESTED_OFFICE_PROFILES = {
    "zip-aes-office-agile-aes256-docx": ("agile-aes256-docx",),
    "zip-aes-office-two-siblings": ("agile-aes256-docx", "agile-aes256-xlsx"),
}

OFFICE_PASSWORD_PROFILES = tuple(_FIXTURES)
OFFICE_PLAINTEXT_PROFILES = tuple(_PLAINTEXT)


def _decode_fixture(table: dict[str, tuple[str, int, str]], profile: str) -> bytes:
    if profile not in table:
        raise ValueError("Unknown Office password fixture profile")
    expected_sha256, expected_size, compressed = table[profile]
    payload = zlib.decompress(base64.b85decode(compressed))
    if len(payload) != expected_size or hashlib.sha256(payload).hexdigest() != expected_sha256:
        raise ValueError("Office password fixture checksum differs")
    return payload


def build_office_password_fixture(profile: str, recipe_version: int = 1) -> bytes:
    """Return checksum-verified canonical encrypted test bytes, with public passwords."""
    if recipe_version != 1:
        raise ValueError("Unsupported Office password fixture recipe version")
    return _decode_fixture(_FIXTURES, profile)


def build_office_plaintext_fixture(profile: str, recipe_version: int = 1) -> bytes:
    """Return the exact inert OOXML bytes expected after real decryption.

    Accept a plaintext kind (for example ``docm``) or its encrypted profile. The
    nested ZIP's canonical plaintext is the fully decrypted Word document.
    """
    if recipe_version != 1:
        raise ValueError("Unsupported Office password fixture recipe version")
    if profile in {"zip-aes-office-agile-aes256-docx", "agile-aes256-docx-second-password"}:
        profile = "docx"
    for prefix in ("agile-aes256-", "standard-aes128-"):
        profile = profile.removeprefix(prefix)
    return _decode_fixture(_PLAINTEXT, profile)
